import { HttpErrorResponse } from '@angular/common/http';
import { inject, Injectable } from '@angular/core';
import { BehaviorSubject, EMPTY, Observable } from 'rxjs';
import { catchError, tap } from 'rxjs/operators';
import { DataApiService } from '../../../services/data-api.service';
import { MensajesHttpService } from '../../../utils/mensajesHttp/mensajes-http.service';
import { DataApi } from '../../../Model/dataApi';

@Injectable({
  providedIn: 'root',
})
export class LotesFacadeService {

  private dataApi = inject(DataApiService);
  private _mensajesHttp = inject(MensajesHttpService);

  private Cargando$ = new BehaviorSubject<boolean>(false);
  public responseCargando$: Observable<boolean> = this.Cargando$.asObservable();

  private Lotes$ = new BehaviorSubject<any[]>([]);
  public responseLotes$: Observable<any[]> = this.Lotes$.asObservable();

  private LotesProducto$ = new BehaviorSubject<any[]>([]);
  public responseLotesProducto$: Observable<any[]> = this.LotesProducto$.asObservable();

  constructor() { }

  MostrarLotes(params: any) {
    this.Cargando$.next(true);
    this.Lotes$.next([]);
    const request$ = this.dataApi.GetDataApi(`inventario/v1/Lotes/`, params).pipe(
      tap((result: DataApi | any) => {
        this.Cargando$.next(false);
        this.Lotes$.next(result.data.Table0);
      }),
      catchError((error: HttpErrorResponse) => {
        this.Cargando$.next(false);
        this.Lotes$.next([]);
        this._mensajesHttp.mostrarErrorHttp(error, 'Ocurrio un error al mostrar las lotes', '');
        return EMPTY;
      })
    );

    return request$.subscribe();
  }


  MostrarLotesProducto(params: any, callback) {
    this.Cargando$.next(true);
    this.Lotes$.next([]);
    const request$ = this.dataApi.GetDataApi(`inventario/v1/lotes/producto/`, params).pipe(
      tap((result: DataApi | any) => {
        this.Cargando$.next(false);
        callback(result.data.Table0);
      }),
      catchError((error: HttpErrorResponse) => {
        this.Cargando$.next(false);
        callback([]);
        this._mensajesHttp.mostrarErrorHttp(error, 'Ocurrio un error al mostrar los lotes del producto', '');
        return EMPTY;
      })
    );

    return request$.subscribe();
  }

  InsertarLotes(params: any, respuesta) {
    this.Cargando$.next(true);
    const request$ = this.dataApi.PostDataApi(`inventario/v1/lotes/`, params).pipe(
      tap((result: DataApi | any) => {
        respuesta(result);
      }),
      catchError((error: HttpErrorResponse) => {
        this.Cargando$.next(false);
        this._mensajesHttp.mostrarErrorHttp(error, 'Ocurrio un error al insertar el lote', '');
        return EMPTY;
      })
    );

    return request$.subscribe();
  }

  ActualizarLotes(params: any, respuesta) {
    this.Cargando$.next(true);
    const request$ = this.dataApi.PutDataApi(`inventario/v1/lotes/`, params).pipe(
      tap((result: DataApi | any) => {
        respuesta(result);

      }),
      catchError((error: HttpErrorResponse) => {
        this.Cargando$.next(false);
        this._mensajesHttp.mostrarErrorHttp(error, 'Ocurrio un error al actualizar el lote', '');
        return EMPTY;
      })
    );

    return request$.subscribe();
  }
}
